/**
 * Seeded randomness (ARCHITECTURE §4.2): sfc32, seeded through cyrb128.
 *
 * Seeds: a practice run uses its runId (a UUID from crypto.getRandomValues,
 * generated by the controller). The mock server forks
 * `attempt:<id>:round:<n>` for option shuffles. Tests pass literal seeds.
 * SQL never reproduces this generator: sealed shuffles are drawn with
 * gen_random_bytes and stored per attempt, so parity tests compare judged
 * results, never shuffles.
 */

export interface Rng {
  /** [0, 1) */
  next(): number;
  /** An integer in [0, maxExclusive). */
  int(maxExclusive: number): number;
  /** Fisher-Yates, returns a copy. */
  shuffle<T>(items: readonly T[]): T[];
  pick<T>(items: readonly T[]): T;
  /** An independent stream, stable for the same label. */
  fork(label: string): Rng;
}

/**
 * cyrb128: four 32-bit words from a string, hashed over its UTF-16 code
 * units, so the same seed gives the same state on every machine.
 */
export function cyrb128(seed: string): [number, number, number, number] {
  let h1 = 1779033703;
  let h2 = 3144134277;
  let h3 = 1013904242;
  let h4 = 2773480762;
  for (let i = 0; i < seed.length; i += 1) {
    const k = seed.charCodeAt(i);
    h1 = h2 ^ Math.imul(h1 ^ k, 597399067);
    h2 = h3 ^ Math.imul(h2 ^ k, 2869860233);
    h3 = h4 ^ Math.imul(h3 ^ k, 951274213);
    h4 = h1 ^ Math.imul(h4 ^ k, 2716044179);
  }
  h1 = Math.imul(h3 ^ (h1 >>> 18), 597399067);
  h2 = Math.imul(h4 ^ (h2 >>> 22), 2869860233);
  h3 = Math.imul(h1 ^ (h3 >>> 17), 951274213);
  h4 = Math.imul(h2 ^ (h4 >>> 19), 2716044179);
  h1 ^= h2 ^ h3 ^ h4;
  h2 ^= h1;
  h3 ^= h1;
  h4 ^= h1;
  return [h1 >>> 0, h2 >>> 0, h3 >>> 0, h4 >>> 0];
}

/** sfc32 over 32-bit words; each call returns a float in [0, 1). */
function sfc32(
  seedA: number,
  seedB: number,
  seedC: number,
  seedD: number,
): () => number {
  let a = seedA | 0;
  let b = seedB | 0;
  let c = seedC | 0;
  let d = seedD | 0;
  return () => {
    const t = (((a + b) | 0) + d) | 0;
    d = (d + 1) | 0;
    a = b ^ (b >>> 9);
    b = (c + (c << 3)) | 0;
    c = (c << 21) | (c >>> 11);
    c = (c + t) | 0;
    return (t >>> 0) / 4294967296;
  };
}

/**
 * Fork seeds are derived from the parent seed and the label alone, never
 * from how much of the parent stream was used, with the parent's length
 * prefixed so ("a/b", "c") and ("a", "b/c") can't collide.
 */
function forkSeed(seed: string, label: string): string {
  return `${seed.length}:${seed}|${label}`;
}

export function createRng(seed: string): Rng {
  const next = sfc32(...cyrb128(seed));
  const int = (maxExclusive: number): number => {
    if (!Number.isInteger(maxExclusive) || maxExclusive < 1) {
      throw new RangeError(
        `rng.int needs a positive integer bound, got ${maxExclusive}`,
      );
    }
    return Math.floor(next() * maxExclusive);
  };
  return {
    next,
    int,
    shuffle<T>(items: readonly T[]): T[] {
      const out = items.slice();
      for (let i = out.length - 1; i > 0; i -= 1) {
        const j = int(i + 1);
        const held = out[i] as T;
        out[i] = out[j] as T;
        out[j] = held;
      }
      return out;
    },
    pick<T>(items: readonly T[]): T {
      if (items.length === 0) throw new RangeError("rng.pick needs items");
      return items[int(items.length)] as T;
    },
    fork(label: string): Rng {
      return createRng(forkSeed(seed, label));
    },
  };
}
